set-variable.value:
@{
        var capSeconds = int.Parse("{{riverside-max-retry-after-seconds}}");
        var raw = context.Response.Headers.GetValueOrDefault("Retry-After", "1");
        int seconds;
        return int.TryParse(raw, out seconds) ? Math.Max(1, Math.Min(capSeconds, seconds)) : 1;
      }

return-response.set-body:
@{
          var timeout = context.Response.StatusCode == 504;
          var retryCount = Math.Max(0, (int)context.Variables.GetValueOrDefault("riversideBackendAttempt", 1) - 1);
          return new JObject(
            new JProperty("error", new JObject(
              new JProperty("code", timeout ? "timeout" : "overloaded"),
              new JProperty("message", timeout ? "The backend did not complete within the request deadline." : "The service is temporarily unavailable."),
              new JProperty("type", timeout ? "deadline_error" : "capacity_error"),
              new JProperty("param", null),
              new JProperty("retryable", true),
              new JProperty("retry_after_seconds", (int)context.Variables["riversideSafeRetryAfter"]))),
            new JProperty("trace", new JObject(
              new JProperty("trace_id", (string)context.Variables["riversideTraceId"]),
              new JProperty("retry_count", retryCount)))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }

set-status.code:
@{
          var status = context.Response.StatusCode;
          return new [] { 400, 401, 403 }.Contains(status) ? status : 502;
        }

return-response.set-body:
@{
          var status = context.Response.StatusCode;
          var code = status == 400 ? "invalid_request" : status == 401 ? "unauthorized" : status == 403 ? "forbidden" : "backend_failure";
          var type = status == 400 ? "request_error" : status == 401 ? "authentication_error" : status == 403 ? "authorization_error" : "backend_error";
          var message = status == 400 ? "The backend rejected the request." : status == 401 ? "Backend authentication failed." : status == 403 ? "The request is not authorized." : "The backend could not complete the request.";
          var retryCount = Math.Max(0, (int)context.Variables.GetValueOrDefault("riversideBackendAttempt", 1) - 1);
          return new JObject(
            new JProperty("error", new JObject(
              new JProperty("code", code),
              new JProperty("message", message),
              new JProperty("type", type),
              new JProperty("param", null),
              new JProperty("retryable", false))),
            new JProperty("trace", new JObject(
              new JProperty("trace_id", (string)context.Variables["riversideTraceId"]),
              new JProperty("retry_count", retryCount)))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }
